// Standard contour representation in Retiam:
// Quadratic Bézier coordinate stream [startX, startY, cp1X, cp1Y, ep1X, ep1Y, ...]
export type PathContour = number[];

// Multiple contours forming a complete vector path shape
export type PathContours = PathContour[];

export interface IPathModifier {
    readonly id: string;
    enabled: boolean;
    isDirty: boolean;
    attach(path: Path): void;
    detach(): void;
    invalidate(): void;
    apply(contours: PathContours): PathContours;
}

const wiggle = new WiggleModifier({
    amplitude: 0.15,
    frequency: 3.5,
    octaves: 3,
    phase: 0.0
});
path.addModifier(wiggle);

import { Circle, PathContours, Vec2 } from "retiam";

const circle = new Circle({ radius: 1.5, strokeWidth: 0.05, strokeColor: "#00E5FF" });

let phase = 0;

// Attach inline transformation lambda
circle.modify((contours: PathContours) => {
    return contours.map((contour) => {
        const deformedPts = contour.points.map((pt) => {
            const angle = Math.atan2(pt.y, pt.x);
            const dist = Math.hypot(pt.x, pt.y);
            const displacement = Math.sin(angle * 6 + phase) * 0.15;
            return new Vec2(pt.x * (1 + displacement / dist), pt.y * (1 + displacement / dist));
        });
        return { points: deformedPts, closed: contour.closed };
    });
}, "PolarWaveWarp");

// In animation frame:
phase += 0.05;
circle.invalidateModifiers(); // Recalculates pipeline and updates WebGPU buffers

import { PathModifier, PathContours, Vec2 } from "retiam";

export interface AttractorOptions {
    point?: Vec2;
    strength?: number;
    radius?: number;
}

export class AttractorModifier extends PathModifier {
    private _point: Vec2 = new Vec2(0, 0);
    private _strength: number = 0.8;
    private _radius: number = 2.0;

    constructor(options?: AttractorOptions) {
        super("Attractor");
        if (options?.point) this._point.set(options.point);
        if (options?.strength !== undefined) this._strength = options.strength;
        if (options?.radius !== undefined) this._radius = options.radius;
    }

    // Reactive properties automatically trigger WebGPU buffer rebuilds
    public get point(): Vec2 { return this._point; }
    public set point(val: Vec2) {
        this._point.set(val);
        this.invalidate();
    }

    public get strength(): number { return this._strength; }
    public set strength(val: number) {
        if (this._strength !== val) {
            this._strength = val;
            this.invalidate();
        }
    }

    public apply(contours: PathContours): PathContours {
        return contours.map((contour) => {
            const deformed = contour.points.map((pt) => {
                const dx = this._point.x - pt.x;
                const dy = this._point.y - pt.y;
                const dist = Math.hypot(dx, dy);

                if (dist >= this._radius || dist < 0.0001) return pt.clone();

                // Smooth cubic falloff: f(u) = 1 - 3u^2 + 2u^3
                const u = dist / this._radius;
                const factor = (1 - u * u * (3 - 2 * u)) * this._strength;

                return new Vec2(pt.x + dx * factor, pt.y + dy * factor);
            });
            return { points: deformed, closed: contour.closed };
        });
    }
}
